const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Nassau County, New York geometry (bounding box)
  const nassauCounty = ee.Geometry.Rectangle([-73.77, 40.55, -73.25, 40.95]);

  // Define date ranges for October 1-23
  const startDay = '01';
  const endDay = '23';

  const date2018 = ee.DateRange('2018-10-01', '2018-10-24');
  const date2019 = ee.DateRange('2019-10-01', '2019-10-24');
  const date2021 = ee.DateRange('2021-10-01', '2021-10-24');

  // Sentinel-5P TROPOMI NO2 collection
  const collection2018 = ee.ImageCollection('COPERNICUS/S5P/NRTI_NO2')
    .filterBounds(nassauCounty)
    .filterDate(date2018)
    .select('NO2_column_number_density');

  const collection2019 = ee.ImageCollection('COPERNICUS/S5P/NRTI_NO2')
    .filterBounds(nassauCounty)
    .filterDate(date2019)
    .select('NO2_column_number_density');

  const collection2021 = ee.ImageCollection('COPERNICUS/S5P/NRTI_NO2')
    .filterBounds(nassauCounty)
    .filterDate(date2021)
    .select('NO2_column_number_density');

  // Check collection sizes
  const size2018 = collection2018.size().getInfo();
  const size2019 = collection2019.size().getInfo();
  const size2021 = collection2021.size().getInfo();

  print('2018 Images: ' + size2018);
  print('2019 Images: ' + size2019);
  print('2021 Images: ' + size2021);

  // Check for empty collections
  if (size2018 === 0 || size2019 === 0 || size2021 === 0) {
    print('Empty Collection (No images found for one or more years)');
    print('C1');
    return;
  }

  // Mosaic images and apply QA filtering
  const img2018 = collection2018.mean();
  const img2019 = collection2019.mean();
  const img2021 = collection2021.mean();

  // Calculate mean NO2 concentrations
  const stats2018 = img2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nassauCounty,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2019 = img2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nassauCounty,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2021 = img2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: nassauCounty,
    scale: 3000,
    maxPixels: 1e9
  });

  const no2_2018 = stats2018.get('NO2_column_number_density').getInfo();
  const no2_2019 = stats2019.get('NO2_column_number_density').getInfo();
  const no2_2021 = stats2021.get('NO2_column_number_density').getInfo();

  // Validation
  if (no2_2018 === null || no2_2019 === null || no2_2021 === null) {
    print('Calculation Failure: Null values returned');
    print('C3');
    return;
  }

  if (isNaN(no2_2018) || isNaN(no2_2019) || isNaN(no2_2021)) {
    print('Calculation Failure: NaN values returned');
    print('C3');
    return;
  }

  // Print results
  print('2018 Mean NO2: ' + no2_2018.toFixed(4) + ' mol/m²');
  print('2019 Mean NO2: ' + no2_2019.toFixed(4) + ' mol/m²');
  print('2021 Mean NO2: ' + no2_2021.toFixed(4) + ' mol/m²');

  // Compare 2021 vs 2018 and 2019
  const lower_than_2018 = no2_2021 < no2_2018;
  const lower_than_2019 = no2_2021 < no2_2019;

  print('2021 lower than 2018: ' + lower_than_2018);
  print('2021 lower than 2019: ' + lower_than_2019);

  if (lower_than_2018 && lower_than_2019) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
